//! URL parser re-implemented from the observed behavior of the C++ `url_parser` library.
//!
//! Parsing pipeline (matches the reference binary byte-for-byte):
//! 1. Truncate the input at the first `#` (fragment is discarded).
//! 2. Split off the query at the first `?`.
//! 3. Look for `://` in the remainder: the prefix becomes the scheme
//!    (ASCII-lowercased). Without `://` the whole remainder is the path.
//! 4. With a scheme, the authority runs up to the first `/`; the rest is the path.
//! 5. Userinfo is stripped up to the first `@` in the authority.
//! 6. The host runs up to the first `:`; the remainder is parsed as the port.

/// A parsed URL. `port` is `-1` when absent or invalid.
pub struct Url {
    pub scheme: String,
    pub host: String,
    pub port: i64,
    pub path: String,
    pub query: String,
}

impl Url {
    pub fn new(input: &str) -> Url {
        // 1. Discard the fragment: everything from the first '#'.
        let no_fragment = match input.find('#') {
            Some(i) => &input[..i],
            None => input,
        };

        // 2. Split off the query at the first '?'.
        let (main, query) = match no_fragment.find('?') {
            Some(i) => (&no_fragment[..i], no_fragment[i + 1..].to_string()),
            None => (no_fragment, String::new()),
        };

        let mut url = Url {
            scheme: String::new(),
            host: String::new(),
            port: -1,
            path: String::new(),
            query,
        };

        // 3. Scheme: everything before "://", ASCII-lowercased.
        let rest = match main.find("://") {
            Some(i) => {
                url.scheme = main[..i].to_ascii_lowercase();
                &main[i + 3..]
            }
            None => {
                // No scheme: the whole remainder is the path.
                url.path = main.to_string();
                return url;
            }
        };

        // 4. Authority ends at the first '/'; the rest is the path.
        let (authority, path) = match rest.find('/') {
            Some(i) => (&rest[..i], &rest[i..]),
            None => (rest, ""),
        };
        url.path = path.to_string();

        // 5. Strip userinfo up to the first '@'.
        let hostport = match authority.find('@') {
            Some(i) => &authority[i + 1..],
            None => authority,
        };

        // 6. Host ends at the first ':'; the remainder is the port.
        match hostport.find(':') {
            Some(i) => {
                url.host = hostport[..i].to_string();
                url.port = parse_port(&hostport[i + 1..]);
            }
            None => url.host = hostport.to_string(),
        }

        url
    }
}

/// Parse a port the way `strtol` would: skip leading whitespace, accept an
/// optional sign, require at least one digit, stop at the first non-digit,
/// saturate on overflow. Valid range is 0..=65535; anything else yields -1.
fn parse_port(s: &str) -> i64 {
    let bytes = s.as_bytes();
    let mut i = 0;

    while i < bytes.len() && bytes[i].is_ascii_whitespace() {
        i += 1;
    }

    let negative = if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        let neg = bytes[i] == b'-';
        i += 1;
        neg
    } else {
        false
    };

    if i >= bytes.len() || !bytes[i].is_ascii_digit() {
        return -1;
    }

    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value.saturating_mul(10).saturating_add((bytes[i] - b'0') as i64);
        i += 1;
    }

    if negative {
        value = -value;
    }

    if value < 0 || value > 65535 {
        -1
    } else {
        value
    }
}

