mod url_parser;

use url_parser::Url;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        std::process::exit(1);
    }

    let parser = Url::new(&args[1]);

    println!("{}", parser.scheme);
    println!("{}", parser.host);
    println!("{}", parser.port);
    println!("{}", parser.path);
    println!("{}", parser.query);
}

